        i += 1
cards = []
for c in raw:
    if isinstance(c, dict) and c.get('cardNumber'):
        cn = str(c.get('cardNumber'))
        l4 = str(c.get('cardNumberLast4') or cn[-4:])
        cards.append(dict(num=cn, l4=l4, name=okname(c.get('productName')), main=str(c.get('isMainCard')).lower() != 'false'))
vars['cards_json'] = json.dumps(cards, ensure_ascii=False)
vars['card_count'] = str(len(cards))
vars['card_tries'] = '0'
vars['cards_read'] = '[]'
rc = str(vars.get('cards_rc') or vars.get('load_cards_response.data.result.returnCode') or '')
sc = str(vars.get('load_cards_status_code') or vars.get('load_cards_response.status_code') or '')
if cards:
    vars['cards_state'] = 'one' if len(cards) == 1 else 'multi'
elif rc == 'FB_IVR_CHANNEL_102' or sc == '404':
