        ex.append(c['name'])
if len(ex) >= 2:
    exs = 'Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'
elif len(ex) == 1:
    exs = 'Örneğin, ' + ex[0] + ' diyebilirsiniz.'
else:
    exs = 'Kartınızın son dört hanesini söyleyebilirsiniz.'
vars['card_examples'] = exs
vars['select_hint'] = 'Hangi kartınızın borcunu öğrenmek istersiniz? ' + exs
vars['card_pick'] = ''
if len(cards) == 1:
    vars['sel_num'] = cards[0]['num']
