    vars['sel_name'] = cards[0]['name']
''', 'select_card', [tr('end_agent_error', 'cards_state', 'error'), tr('end_no_card', 'cards_state', 'none'), tr('load_balance', 'cards_state', 'one')])

nodes['select_card'] = conv('select_card', '{{select_hint}}',
