def code_node(name, body, default_next, transitions):
    code = HELP + '\ntry:\n' + '\n'.join('    ' + l for l in body.strip('\n').split('\n')) + '\nexcept Exception as e:\n    vars["err_' + name + '"] = str(e)[:200]\n'
    assert '{{' not in code and '}}' not in code, name
    return {
        'name': name, 'node_type': 'code', 'passthrough': True,
        'passthrough_default_transition': default_next, 'on_enter': {'type': 'silent'},
        'disable_inactivity_monitor': True,
        'pre_actions': [{'type': 'function', 'function': {'name': 'code_exec', 'handler': '__function__:code_exec',
            'parameters': {'type': 'object', 'properties': {'code': {'type': 'string', 'default': code}, 'timeout_ms': {'type': 'number', 'default': 15000}}}}}],
        'transitions': transitions + [{'target_node': default_next, 'description': 'always', 'condition': {'operator': 'always'}}],
    }


def api_node(name, path, data_props, mapping, next_node, retries=1):
    props = {k: {'type': 'string', 'default': v} for k, v in data_props.items()}
    return {
        'name': name, 'node_type': 'api_request', 'passthrough': True,
        'passthrough_default_transition': next_node, 'on_enter': {'type': 'silent'},
        'disable_inactivity_monitor': True, 'suppress_tool_results': True,
        'pre_actions': [{'type': 'function', 'config': {'timeoutMs': 20000, 'maxRetries': retries},
            'function': {'name': name, 'handler': '__function__:api_call', 'description': 'Freya Bank ' + path,
                'parameters': {'type': 'object', 'properties': {
                    'url': {'type': 'string', 'default': BASE + '/' + path},
                    'method': {'type': 'string', 'default': 'POST'},
                    'headers': {'type': 'object', 'properties': {
                        'Content-Type': {'type': 'string', 'default': 'application/json'},
                        'Accept': {'type': 'string', 'default': 'application/json'},
                        'Authorization': {'type': 'string', 'default': 'Bearer test'}}},
                    'body': {'type': 'object', 'properties': {
                        'data': {'type': 'object', 'properties': props},
                        'call': {'type': 'object', 'properties': {'ani': {'type': 'string', 'default': 'unknown'}, 'lang': {'type': 'string', 'default': 'tr'}}}}}}}}}],
        'response_mapping': mapping,
        'transitions': [{'target_node': next_node, 'description': 'always', 'condition': {'operator': 'always'}}],
    }


def eq(var, val):
    return {'logic': 'or', 'conditions': [{'variable': var, 'operator': 'equals', 'operand': val}]}


def tr(target, var, val, desc=''):
    return {'target_node': target, 'description': desc or (var + '=' + val), 'condition': eq(var, val)}


def end_node(name, msg):
    return {'name': name, 'node_type': 'end_call', 'on_enter': {'type': 'silent'}, 'disable_inactivity_monitor': True,
            'transitions': [], 'terminal': {'type': 'function', 'function': {'name': name, 'handler': '__function__:end_call',
            'parameters': {'type': 'object', 'properties': {'message_mode': {'type': 'string', 'default': 'custom'},
                                                             'spoken_message': {'type': 'string', 'default': msg}}}}}}


def conv(name, tts, task, extraction, transitions, max_turns=6, overflow='end_tries'):
    n = {'name': name, 'node_type': 'conversation', 'on_enter': {'type': 'tts', 'text': tts},
         'task_message': task + '\nBu adımda hiçbir araç çağırma.',
         'extraction_schema': extraction, 'transitions': transitions, 'max_node_turns': max_turns,
         'max_turn_transition': overflow}
    return n


